import React from "react"; //rafce
import "./ClientsList.css";

// ✅ Ahora es un ARRAY, no una función
export const Clients = [
  { title: "Cliente 1", content: "Contenido del post 1" },
  { title: "Cliente 2", content: "Contenido del post 2" },
  { title: "Cliente 3", content: "Contenido del post 3" },
];

const ClientsList = () => {
  const [list, setList] = React.useState(Clients);
  const [query, setQuery] = React.useState("");

  const HandleChange = (e) => {
    const value = e.target.value.toLowerCase();

    if (value === "") {
      setList(Clients);
      setQuery(value);
      return;
    }

    //filtro
    const results = Clients.filter((post) =>
      post.title.toLowerCase().includes(value)
    );

    setQuery(value);
    setList(results);
  };

  return (
    <div>
      <form>
        <div>
          <span>Clientes</span>
          <input
            type="text"
            placeholder="Buscar un cliente..."
            onChange={HandleChange}
            value={query}
          />
        </div>
      </form>

      <div>
        {list.map((post, index) => (
          <div className="card" key={index}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
          </div>
        ))}

        {list.length === 0 && <p>No hay facturas para mostrar</p>}
      </div>
    </div>
  );
};

export default ClientsList;
